-- Warp-Huntress Kula, Broken Isles Dalaran. Preserve the major stops and return
-- along the same supported route instead of cutting back through the city.
START TRANSACTION;

UPDATE creature SET position_z = 738.268 WHERE guid = 272369 AND id = 97512 AND map = 1220;

ON DUPLICATE KEY UPDATE position_x = VALUES(position_x), position_y = VALUES(position_y),
                        position_z = VALUES(position_z);

COMMIT;
